python3 -c "
import json
with open('/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-15-projects-vla-ssd--claude-sessions-reviewer-7b0fefde/2ab22121-e01f-4b40-991c-65244a081251/tool-results/mcp-agent-ml-research-read_registry-1779559290961.txt') as f:
    data = json.load(f)
parsed = json.loads(data['result'])
exps = parsed['data']['experiments']

# Check all experiments with CF data for OpenVLA
for name, exp in exps.items():
    metrics = exp.get('metrics', {})
    metrics_str = json.dumps(metrics)
    # Look for any CF-related metrics
    if any(k in metrics_str.lower() for k in ['counterfactual', 'cf_', 'cohens_d', 'empty_d', 'wrong_d']):
        hyp = exp.get('hypothesis', '')[:80]
        # filter for openvla-related
        if 'openvla' in name.lower() or 'object' in name.lower() or 'spatial' in name.lower() or 'long' in name.lower() or 'counterfactual' in name.lower():
            # Extract just the CF-related values
            cf_keys = [k for k in metrics if any(x in k.lower() for x in ['cf', 'counterfactual', 'empty', 'wrong', 'shuffled', 'para', 'cohens'])]
            cf_data = {k: metrics[k] for k in cf_keys}
            if not cf_data and 'counterfactual' in metrics:
                cf_data = {'counterfactual': metrics['counterfactual']}
            if not cf_data and 'trained_cf' in metrics:
                cf_data = {'trained_cf': metrics['trained_cf']}
            if not cf_data and 'global_cohens_d' in metrics:
                cf_data = {'global_cohens_d': metrics['global_cohens_d']}
            if cf_data:
                print(f'{name}: {json.dumps(cf_data, indent=2)[:400]}')
                print(f'  hyp: {hyp}')
                print()
"

